using SimuCity.Data;
using SimuCity.Forms;

namespace SimuCity;

/// <summary>
/// Entry point of the SIMUCITY application.
/// A WinForms app has a single main thread marked with [STAThread]
/// (required for the clipboard and UI controls), and Application.Run
/// starts the message loop with the main town window.
/// </summary>
internal static class Program
{
    [STAThread]
    private static void Main()
    {
        // Standard WinForms startup generated by the .NET 8 template.
        ApplicationConfiguration.Initialize();

        // Load saved town data (assignments, books, shopping list, wallet)
        // from the JSON file before any window is shown.
        TownDataStore.Load();

        // Show the main town screen and run until the user closes it.
        Application.Run(new MainForm());
    }
}
